<!doctype html>
<html lang="es">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=1920,height=1080,initial-scale=1">
    <title>{{ $competition->tournament->name }} · Transmisión</title>
    <style>
        :root{--navy:#07172b;--blue:#174789;--green:#00a86b;--gold:#f2b705;--line:#37506d;--white:#f7fbff;--muted:#9fb3ca}*{box-sizing:border-box}html,body{width:1920px;height:180px;margin:0;overflow:hidden;background:transparent;font-family:Inter,Arial,sans-serif;color:var(--white)}body{background:linear-gradient(100deg,#06101e 0%,#0b2039 55%,#07172b 100%)}#stage{position:relative;width:1920px;height:180px;border-top:4px solid var(--gold);border-bottom:4px solid var(--blue);overflow:hidden}.slide{display:grid;grid-template-columns:315px 1fr;height:172px;animation:enter .45s ease both}.identity{display:flex;flex-direction:column;justify-content:center;padding:14px 20px;background:linear-gradient(120deg,#173d7c,#0b294e);border-right:2px solid var(--gold)}.live{display:flex;align-items:center;gap:8px;color:#ffdc64;font-size:13px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.live:before{content:"";width:10px;height:10px;border-radius:50%;background:#ff3c4f;box-shadow:0 0 0 5px rgba(255,60,79,.18);animation:pulse 1.4s infinite}.tournament{margin-top:9px;font-size:24px;font-weight:1000;line-height:1.05;text-transform:uppercase}.counter{margin-top:9px;color:#b9cee5;font-size:12px}.content{display:grid;grid-template-rows:43px 1fr;padding:7px 14px 8px}.heading{display:flex;align-items:center;gap:14px;min-width:0}.phase{font-size:21px;font-weight:1000;text-transform:uppercase}.context{padding:5px 10px;border-radius:999px;background:#173d7c;color:#fff;font-size:13px;font-weight:900}.updated{margin-left:auto;color:var(--muted);font-size:12px}.zone-layout{display:grid;grid-template-columns:1.55fr .95fr;gap:12px;min-height:0}.matches{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.match{min-width:0;padding:6px 9px;border:1px solid var(--line);border-left:5px solid #71849a;border-radius:7px;background:rgba(14,36,62,.94)}.match.called{border-color:var(--gold);border-left-color:var(--gold);background:rgba(83,64,5,.92)}.match.in_progress{border-color:var(--green);border-left-color:var(--green);background:rgba(4,67,48,.94)}.match.completed{border-left-color:#3f8cff;background:rgba(18,51,90,.94)}.match-title{display:flex;justify-content:space-between;gap:8px;color:#8fb5e6;font-size:10px;font-weight:900;text-transform:uppercase}.table{color:#ffd957}.player{display:flex;justify-content:space-between;gap:7px;padding-top:3px;font-size:12px;font-weight:800;white-space:nowrap;overflow:hidden}.player span:first-child{overflow:hidden;text-overflow:ellipsis}.player.winner{color:#5aeda7}.score{flex:none;font-size:13px}.standings{width:100%;border-collapse:collapse;background:rgba(7,22,40,.8);font-size:10px}.standings th{padding:4px;background:#07844d;color:#fff;text-transform:uppercase}.standings td{padding:4px 6px;border:1px solid #2d4561;text-align:center}.standings td:nth-child(2){max-width:180px;text-align:left;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.bracket-layout{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px;align-items:center}.empty{display:grid;place-items:center;height:100%;color:var(--muted);font-size:18px}.progress{position:absolute;left:0;bottom:0;height:4px;background:var(--gold);animation:progress linear both}@keyframes enter{from{opacity:0;transform:translateX(28px)}to{opacity:1;transform:none}}@keyframes pulse{50%{opacity:.45}}@keyframes progress{from{width:0}to{width:100%}}
        html,body{width:1920px;height:1080px}
        #stage{width:1920px;height:1080px;border-top-width:8px;border-bottom-width:8px}
        .slide{grid-template-columns:1fr;grid-template-rows:104px 1fr;height:1064px}
        .identity{flex-direction:row;align-items:center;justify-content:flex-start;gap:30px;padding:13px 34px;border-right:0;border-bottom:4px solid var(--gold)}
        .live{flex:none;gap:14px;font-size:20px}.live:before{width:16px;height:16px;box-shadow:0 0 0 8px rgba(255,60,79,.18)}
        .tournament{margin:0;font-size:34px;line-height:1.08}.tournament-data{display:flex;align-items:center;gap:24px;margin-left:auto;color:#d5e2f0;font-size:14px}.tournament-data span{display:flex;flex-direction:column;gap:3px;max-width:250px}.tournament-data small{color:#79a2cf;font-size:9px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.tournament-data b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}
        .counter{margin-top:26px;font-size:20px}
        .content{grid-template-rows:76px 1fr;padding:16px 28px 28px}
        .heading{gap:24px}.phase{font-size:34px}.context{padding:9px 17px;font-size:20px}.updated{font-size:17px}
        .zone-layout{grid-template-columns:1.35fr .65fr;gap:24px}
        .matches{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(3,minmax(0,1fr));gap:18px}
        .match{display:flex;flex-direction:column;justify-content:center;padding:20px 24px;border-width:2px;border-left-width:9px;border-radius:14px}
        .match-title{font-size:18px}.player{padding-top:15px;font-size:26px}.score{font-size:29px}
        .standings{font-size:20px}.standings th{padding:16px}.standings td{padding:18px 14px;border-width:2px}.standings td:nth-child(2){max-width:360px}
        .bracket-layout{grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(2,minmax(0,1fr));gap:24px}
        .empty{font-size:32px}.progress{height:8px}
        .zones-grid{display:grid;gap:18px;min-height:0;align-content:start;align-items:start}.zone-panel{display:grid;grid-template-rows:52px auto;min-width:0;overflow:hidden;border:2px solid #37506d;border-radius:14px;background:rgba(8,28,50,.88)}.zone-name{display:flex;align-items:center;justify-content:space-between;padding:0 17px;background:#174789;font-size:20px;font-weight:1000;text-transform:uppercase}.zone-card-body{padding:11px}.zone-bracket-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(3,104px);gap:8px 12px;align-items:stretch}.mini-match{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto auto auto;gap:3px 8px;align-content:center;min-width:0;padding:8px 10px;border:1px solid #37506d;border-left:5px solid #71849a;border-radius:7px;background:#102a47}.mini-match.called{border-color:var(--gold);border-left-color:var(--gold);background:#514008}.mini-match.in_progress{border-color:var(--green);border-left-color:var(--green);background:#064c36}.mini-match.completed{border-left-color:#3f8cff}.mini-title{grid-column:1/-1;display:flex;justify-content:space-between;gap:6px;color:#8fb5e6;font-size:9px;font-weight:900;text-transform:uppercase}.mini-player{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;font-weight:850}.mini-player.winner{color:#5aeda7}.mini-score{font-size:12px}.z-m1{grid-column:1;grid-row:1}.z-m2{grid-column:1;grid-row:2}.z-loss{grid-column:1;grid-row:3}.z-win{grid-column:2;grid-row:1}.z-second{grid-column:2;grid-row:3}.zone-place{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:0;padding:8px;border:2px solid #2164b8;border-radius:8px;background:#0d2038;text-align:center}.zone-place small{color:#438ddd;font-size:9px;font-weight:900;text-transform:uppercase}.zone-place strong{display:block;max-width:100%;margin-top:5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.z-first-place{grid-column:3;grid-row:1}.z-runner-place{grid-column:3;grid-row:3}.zone-standings{grid-column:2/4;grid-row:2;width:100%;height:100%;border-collapse:collapse;background:#07172b;font-size:9px}.zone-standings th{height:19px;padding:2px 4px;background:#07844d}.zone-standings td{height:20px;padding:2px 5px;border:1px solid #2d4561;text-align:center}.zone-standings td:nth-child(2){max-width:270px;text-align:left;font-weight:850;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.zones-grid.dense{gap:12px}.zones-grid.dense .zone-panel{grid-template-rows:34px auto;border-radius:9px}.zones-grid.dense .zone-name{padding:0 10px;font-size:14px}.zones-grid.dense .zone-card-body{padding:6px}.zones-grid.dense .zone-bracket-grid{grid-template-rows:repeat(3,64px);gap:4px 6px}.zones-grid.dense .mini-match{padding:3px 5px;border-radius:5px}.zones-grid.dense .mini-title,.zones-grid.dense .zone-place small{font-size:7px}.zones-grid.dense .mini-player,.zones-grid.dense .mini-score,.zones-grid.dense .zone-place strong,.zones-grid.dense .zone-standings{font-size:8px}.zones-grid.dense .zone-standings th,.zones-grid.dense .zone-standings td{height:12px;padding:1px 3px}
    </style>
</head>
<body>
<main id="stage"><div class="empty">Cargando resultados en vivo…</div></main>
<script>
const endpoint=@json($jsonUrl),config=@json($broadcastConfig),stage=document.querySelector('#stage');
let data=null,slides=[],activeSlide=0,lastPayload='',loading=false,rotationTimer=null;
const esc=value=>String(value??'—').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const matchState=match=>['called','in_progress','completed'].includes(match.estado)?match.estado:'';
const score=(match,side)=>{if(match.estado!=='completed'&&match.estado!=='in_progress')return '—';const values=match.sets_computables||[];return esc(values[side]??'—')};
function identity(){return '<header class="identity"><div class="live">Resultados en vivo</div><div class="tournament">'+esc(data.torneo)+'</div><div class="tournament-data"><span><small>Sede</small><b>'+esc(data.sede||'Sin informar')+'</b></span><span><small>Fecha</small><b>'+esc(data.fecha||'Sin informar')+'</b></span><span><small>Tipo</small><b>'+esc([data.tipo_torneo,data.caracter].filter(Boolean).join(' · ')||'Sin informar')+'</b></span><span><small>Modalidad</small><b>'+esc(data.modalidad||'Sin informar')+'</b></span></div></header>'}
function matchCard(match){const winner=match.ganador||'';return '<article class="match '+matchState(match)+'"><div class="match-title"><span>'+esc(match.etiqueta||('Ronda '+match.ronda))+'</span>'+(match.mesa?'<span class="table">Mesa '+esc(match.mesa)+'</span>':'')+'</div><div class="player '+(winner===match.jugador_1?'winner':'')+'"><span>'+esc(match.jugador_1||'A definir')+'</span><b class="score">'+score(match,0)+'</b></div><div class="player '+(winner===match.jugador_2?'winner':'')+'"><span>'+esc(match.jugador_2||'A definir')+'</span><b class="score">'+score(match,1)+'</b></div></article>'}
function zoneMatchPosition(match){const label=String(match.etiqueta||'').toLocaleLowerCase('es');if(label==='partido 1')return'z-m1';if(label==='partido 2')return'z-m2';if(label.includes('primer puesto'))return'z-win';if(label.includes('segundo puesto'))return'z-second';if(label.includes('perdedores')||label.includes('recuperación'))return'z-loss';return''}
function miniMatchCard(match){const winner=match.ganador||'';return '<article class="mini-match '+zoneMatchPosition(match)+' '+matchState(match)+'"><div class="mini-title"><span>'+esc(match.etiqueta||('Ronda '+match.ronda))+'</span>'+(match.mesa?'<span class="table">Mesa '+esc(match.mesa)+'</span>':'')+'</div><span class="mini-player '+(winner===match.jugador_1?'winner':'')+'">'+esc(match.jugador_1||'A definir')+'</span><b class="mini-score">'+score(match,0)+'</b><span class="mini-player '+(winner===match.jugador_2?'winner':'')+'">'+esc(match.jugador_2||'A definir')+'</span><b class="mini-score">'+score(match,1)+'</b></article>'}
function zonePanel(phase,zone){const matches=phase.partidos.filter(match=>Number(match.zona_id)===Number(zone.id)),standings=zone.jugadores.slice().sort((a,b)=>(a.clasificacion||99)-(b.clasificacion||99)),first=standings.find(row=>Number(row.clasificacion)===1)?.nombre||'A definir',second=standings.find(row=>Number(row.clasificacion)===2)?.nombre||'A definir';return '<section class="zone-panel"><div class="zone-name"><span>'+esc(zone.nombre)+'</span><span>'+esc(zone.horario||'Sin horario')+'</span></div><div class="zone-card-body"><div class="zone-bracket-grid">'+matches.map(miniMatchCard).join('')+'<div class="zone-place z-first-place"><small>1.er puesto</small><strong>'+esc(first)+'</strong></div><table class="zone-standings"><thead><tr><th>Pos</th><th>Jugador</th><th>PG</th><th>DS</th><th>Prom</th></tr></thead><tbody>'+standings.map(row=>'<tr><td>'+esc(row.clasificacion)+'</td><td>'+esc(row.nombre)+'</td><td>'+esc(row.partidos_ganados)+'</td><td>'+esc(row.diferencia_sets)+'</td><td>'+esc(row.promedio)+'</td></tr>').join('')+'</tbody></table><div class="zone-place z-runner-place"><small>2.º puesto</small><strong>'+esc(second)+'</strong></div></div></div></section>'}
function zoneScheduleSlide(phase,slotKey,zones){const count=zones.length,columns=count<=3?count:(count===4?2:3),dense=count>3?' dense':'';return {key:'zones-'+phase.id+'-'+slotKey,html:'<div class="heading"><div class="phase">'+esc(phase.nombre)+'</div><div class="context">'+esc(zones[0]?.horario||'Sin horario')+'</div></div><div class="zones-grid'+dense+'" style="grid-template-columns:repeat('+columns+',minmax(0,1fr))">'+zones.map(zone=>zonePanel(phase,zone)).join('')+'</div>'}}
function scheduleMatches(phase,schedule){return phase.partidos.filter(match=>{if(Number(match.ronda)!==Number(schedule.round_number))return false;const from=Number(schedule.from_match||0),to=Number(schedule.to_match||0);return (!from||Number(match.orden)>=from)&&(!to||Number(match.orden)<=to)})}
function bracketSlides(phase){const schedules=phase.horarios_fase?.length?phase.horarios_fase:[{name:'Todos los partidos'}],result=[];schedules.forEach((schedule,scheduleIndex)=>{const matches=phase.horarios_fase?.length?scheduleMatches(phase,schedule):phase.partidos;for(let offset=0;offset<matches.length;offset+=5){result.push({key:'phase-'+phase.id+'-'+scheduleIndex+'-'+offset,html:'<div class="heading"><div class="phase">'+esc(phase.nombre)+'</div><div class="context">'+esc(schedule.name||'Partidos')+'</div></div><div class="bracket-layout">'+matches.slice(offset,offset+5).map(matchCard).join('')+'</div>'})}});return result}
function buildSlides(){const allowedPhases=(config.allPhases?data.fases:data.fases.filter(phase=>config.phaseIds.includes(Number(phase.id)))),allowedSlots=config.allZoneSlots?[]:(config.zoneSlotKeys||[]);slides=allowedPhases.flatMap(phase=>{if(phase.tipo!=='zones')return bracketSlides(phase);const zones=phase.zonas.filter(zone=>!allowedSlots.length||allowedSlots.includes(String(zone.horario_clave))),bySlot=zones.reduce((groups,zone)=>{(groups[String(zone.horario_clave||'without_slot')]??=[]).push(zone);return groups},{});return Object.entries(bySlot).map(([slotKey,slotZones])=>zoneScheduleSlide(phase,slotKey,slotZones))});if(activeSlide>=slides.length)activeSlide=0}
function showSlide(){if(!slides.length){stage.innerHTML='<div class="empty">No hay resultados configurados para la transmisión.</div>';return}const slide=slides[activeSlide];stage.innerHTML='<section class="slide">'+identity()+'<div class="content">'+slide.html+'</div></section><div class="progress" style="animation-duration:'+config.rotationSeconds+'s"></div>';if(!rotationTimer)rotationTimer=setInterval(()=>{if(!slides.length)return;activeSlide=(activeSlide+1)%slides.length;showSlide()},config.rotationSeconds*1000)}
async function refresh(){if(loading)return;loading=true;try{const separator=endpoint.includes('?')?'&':'?',response=await fetch(endpoint+separator+'_='+Date.now(),{cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok)throw new Error('No fue posible obtener los resultados');const payload=await response.json(),signature=JSON.stringify(payload.data);if(signature!==lastPayload){const currentKey=slides[activeSlide]?.key;lastPayload=signature;data=payload.data;buildSlides();const sameIndex=slides.findIndex(slide=>slide.key===currentKey);if(sameIndex>=0)activeSlide=sameIndex;showSlide()}}catch(error){if(!data)stage.innerHTML='<div class="empty">'+esc(error.message)+'</div>'}finally{loading=false}}
refresh();setInterval(()=>{if(!document.hidden)refresh()},4000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});
</script>
</body>
</html>
